" 1;\n}\n\n/* Grid view (xlsx continuous). */\n.ps-gridview {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: auto;\n  display: none;\n  position: relative;\n  background: var(--ps-paper);\n}\n.ps-grid-spacer {\n  position: relative;\n}\n.ps-grid-canvas {\n  position: absolute;\n  top: 0;\n  left: 0;\n  pointer-events: auto;\n}\n\n/* ── Workspace column ────────────────────────────────────────────────────── */\n/* The document views + the spreadsheet rows fused to them (formula row above,\n * sheet tabs below). A flex COLUMN sitting right of any leading panel in the\n * stage row — so the xlsx chrome belongs to the sheet workspace, not the app\n * frame (the old full-width strip sandwich). */\n.ps-workspace {\n  flex: 1 1 auto;\n  min-width: 0;\n  min-height: 0;\n  display: flex;\n  flex-direction: column;\n  position: relative;\n}\n.ps-workspace > .ps-viewer,\n.ps-workspace > .ps-gridview {\n  min-height: 0;\n}\n\n/* ── Formula bar (xlsx) ──────────────────────────────────────────────────── */\n/* Kind-owned visibility (data-active) — a STABLE row of the spreadsheet\n * workspace; cell selection only fills/empties content (data-empty), never\n * reflows the grid (the old pop-in). Fused: tighter than the toolbar, zero gap\n * to the grid below, sharing one hairline. */\n.ps-formula {\n  flex: 0 0 auto;\n  display: none;\n  align-items: center;\n  gap: var(--ps-s2);\n  height: 30px;\n  padding: 0 var(--ps-s2);\n  background: var(--ps-panel);\n  border-bottom: 1px solid var(--ps-hairline);\n}\n.ps-formula[data-active=\"1\"] {\n  display: flex;\n}\n/* Empty state: keep the boxes (stable geometry), dim the affordance. */\n.ps-formula[data-empty=\"1\"] .ps-namebox {\n  min-height: 20px;\n}\n.ps-formula[data-empty=\"1\"] .ps-fx {\n  opacity: 0.4;\n}\n.ps-namebox {\n  font-family: var(--ps-font-mono);\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--ps-accent);\n  min-width: 52px;\n  padding: 3px 8px;\n  border: 1px solid var(--ps-hairline);\n  border-radius: 0;\n  background: var(--ps-inset);\n  font-feature-settings: \"tnum\" 1, \"zero\" 1;\n  text-align: center;\n}\n.ps-fx {\n  font-family: var(--ps-font-mono);\n  font-size: 11px;\n  color: var(--ps-text-faint);\n}\n.ps-fval {\n  font-family: var(--ps-font-mono);\n  font-size: 12px;\n  color: var(--ps-text);\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.ps-fval .ps-disp {\n  color: var(--ps-text-muted);\n  margin-left: 8px;\n}\n\n/* ── Sheet tabs (xlsx) ───────────────────────────────────────────────────── */\n/* Inside the workspace column, attached to the grid's bottom edge (Excel's\n * placement) — tabs flush-left, no full-width padding band. Hidden entirely\n * for single-sheet workbooks (the CSV norm). */\n.ps-tabs {\n  flex: 0 0 auto;\n  display: none;\n  align-items: stretch;\n  gap: 0;\n  height: 30px;\n  padding: 0;\n  background: var(--ps-panel);\n  border-top: 1px solid var(--ps-hairline);\n  overflow-x: auto;\n  scrollbar-width: none;\n}\n.ps-tabs::-webkit-scrollbar {\n  display: none;\n}\n.ps-tabs[data-show=\"1\"] {\n  display: flex;\n}\n.ps-tab {\n  appearance: none;\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  padding: 0 var(--ps-s3);\n  font-family: var(--ps-font-mono);\n  font-size: 12px;\n  color: var(--ps-text-muted);\n  background: transparent;\n  border: none;\n  /* The accent edge points UP — the active tab connects to the grid above it\n   * (Excel's attached-tab read), not down toward the app frame. */\n  border-top: 2px solid transparent;\n  border-right: 1px solid var(--ps-hairline);\n  cursor: pointer;\n  white-space: nowrap;\n  transition: color 0.12s ease, border-color 0.12s ease, background 0.12s ease;\n}\n.ps-tab:hover {\n  color: var(--ps-text);\n}\n.ps-tab[aria-selected=\"true\"] {\n  color: var(--ps-text);\n  border-top-color: var(--ps-accent);\n  background: var(--ps-inset);\n}\n\n/* ── Comments drawer ─────────────────────────────────────────────────────── */\n.ps-comments {\n  position: absolute;\n  top: 0;\n  right: 0;\n  bottom: 0;\n  width: min(320px, 88%);\n  background: var(--ps-panel);\n  border-left: 1px solid var(--ps-hairline);\n  display: flex;\n  flex-direction: column;\n  transform: translateX(100%);\n  opacity: 0;\n  transition: transform 0.24s cubic-bezier(0.2, 0.7, 0.2, 1), opacity 0.24s ease;\n  z-index: 8;\n  box-shadow: var(--ps-shadow);\n}\n.ps-comments[data-open=\"1\"] {\n  transform: translateX(0);\n  opacity: 1;\n}\n.ps-comments-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  height: var(--ps-toolbar-h);\n  padding: 0 var(--ps-s4);\n  border-bottom: 1px solid var(--ps-hairline);\n  font-family: var(--ps-font-mono);\n  font-size: 12px;\n  color: var(--ps-text);\n  font-feature-settings: \"tnum\" 1, \"zero\" 1;\n}\n.ps-comments-list {\n  flex: 1 1 auto;\n  overflow-y: auto;\n  padding: var(--ps-s3);\n  display: flex;\n  flex-direction: column;\n  gap: var(--ps-s2);\n}\n.ps-card {\n  padding: var(--ps-s3);\n  background: var(--ps-inset);\n  border: 1px solid var(--ps-hairline);\n  border-left: 3px solid var(--ps-cc, var(--ps-accent));\n  border-radius: 0;\n  cursor: pointer;\n  transition: border-color 0.12s ease, background 0.12s ease;\n}\n.ps-card:hover {\n  border-color: var(--ps-hairline-strong);\n}\n.ps-card[data-focused=\"1\"] {\n  border-color: var(--ps-accent);\n  background: var(--ps-accent-soft);\n}\n.ps-card-head {\n  display: flex;\n  align-items: baseline;\n  gap: var(--ps-s2);\n  margin-bottom: 6px;\n}\n.ps-card-author {\n  font-family: var(--ps-font-ui);\n  font-weight: 600;\n  font-size: 12px;\n  color: var(--ps-text);\n}\n.ps-card-date {\n  font-family: var(--ps-font-mono);\n  font-size: 10px;\n  color: var(--ps-text-faint);\n  margin-left: auto;\n}\n.ps-card-body {\n  font-family: var(--ps-font-ui);\n  font-size: 15px;\n  line-height: 1.45;\n  color: var(--ps-text-muted);\n  white-space: pre-wrap;\n}\n\n/* ── Search box (find-bar) ───────────────────────────────────────────────── */\n/* A floating find-bar pinned top-right of the stage, opened with ⌘/Ctrl+F.\n * Same panel/hairline language as the toolbar; the ONE accent appears only on\n * the focused input ring + pressed toggles. Hidden until [data-open]. */\n.ps-search {\n  position: absolute;\n  top: var(--ps-s3);\n  right: var(--ps-s3);\n  z-index: 9;\n  display: none;\n  align-items: center;\n  gap: var(--ps-s2);\n  height: 38px;\n  padding: 0 var(--ps-s2);\n  background: var(--ps-panel);\n  border: 1px solid var(--ps-hairline);\n  border-radius: 0;\n  box-shadow: var(--ps-shadow);\n  /* Slide-down reveal to mirror the comments drawer's crafted motion. */\n  transform: translateY(-6px);\n  opacity: 0;\n  transition: transform 0.18s cubic-bezier(0.2, 0.7, 0.2, 1), opacity 0.18s ease;\n}\n.ps-search[data-open] {\n  display: flex;\n  transform: none;\n  opacity: 1;\n}\n\n.ps-search-input {\n  width: min(220px, 38vw);\n  height: 28px;\n  padding: 0 var(--ps-s2);\n  font-family: var(--ps-font-ui);\n  font-size: 12px;\n  color: var(--ps-text);\n  background: var(--ps-inset);\n  border: 1px solid var(--ps-hairline);\n  border-radius: 0;\n  outline: none;\n  transition: border-color 0.12s ease, box-shadow 0.12s ease;\n}\n.ps-search-input::placeholder {\n  color: var(--ps-text-faint);\n}\n.ps-search-input:focus {\n  border-color: var(--ps-accent);\n  box-shadow: 0 0 0 2px var(--ps-accent-soft);\n}\n\n/* \"n / m\" counter — mono tabular so it never jitters as you step matches. */\n.ps-search-count {\n  min-width: 3.4ch;\n  text-align: right;\n  font-family: var(--ps-font-mono);\n  font-size: 11px;\n  color: var(--ps-text-muted);\n  font-feature-settings: \"tnum\" 1, \"zero\" 1;\n}\n.ps-search-count[data-state=\"empty\"] {\n  color: var(--ps-err);\n}\n\n/* Case / whole-word toggles — small mono glyph buttons; pressed = accent. */\n.ps-search-toggles {\n  display: inline-flex;\n  align-items: center;\n  gap: 2px;\n}\n.ps-search-toggle {\n  font-family: var(--ps-font-mono);\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: 0;\n  width: 28px;\n  height: 28px;\n  color: var(--ps-text-muted);\n}\n.ps-search-toggle[aria-pressed=\"true\"] {\n  color: var(--ps-text);\n}\n\n/* Scope segment (Sheet│Book) — reuses the toolbar's segmented-pill language. */\n.ps-search-scope {\n  height: 28px;\n}\n.ps-search-scope .ps-btn {\n  height: 100%;\n  padding: 0 8px;\n  font-family: var(--ps-font-mono);\n  font-size: 11px;\n  color: var(--ps-text-muted);\n}\n\n/* Prev/next cluster + a hairline divider before close. */\n.ps-search-nav {\n  display: inline-flex;\n  align-items: center;\n  gap: 2px;\n}\n.ps-search-nav .ps-btn,\n.ps-search .ps-search-close {\n  width: 26px;\n  height: 28px;\n  font-size: 16px;\n  color: var(--ps-text-muted);\n}\n.ps-search-close {\n  margin-left: 2px;\n  font-size: 17px;\n  border-left: 1px solid var(--ps-hairline);\n  border-radius: 0;\n  padding-left: 6px;\n}\n\n/* ── Loading skeleton ────────────────────────────────────────────────────── */\n.ps-skeleton {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  align-items: flex-start;\n  justify-content: center;\n  padding-top: var(--ps-s5);\n  pointer-events: none;\n  z-index: 2;\n  opacity: 0;\n  visibility: hidden;\n  transition: opacity 160ms ease, visibility 0s linear 160ms;\n}\n.ps-stage[data-loading=\"1\"] .ps-skeleton {\n  opacity: 1;\n  visibility: visible;\n  /* 200ms delay: fast loads never flash the overlay; only slow (CJK) loads show it. */\n  transition: opacity 220ms ease 200ms, visibility 0s linear 200ms;\n}\n/* Centred spinner + label over the shimmer paper. */\n.ps-skel-status {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: var(--ps-s3);\n  color: var(--ps-text-muted);\n  font: 500 12px/1.2 var(--ps-font-ui);\n  letter-spacing: 0.01em;\n}\n.ps-skel-spinner {\n  width: 22px;\n  height: 22px;\n  border-radius: 50%;\n  border: 2px solid color-mix(in srgb, var(--ps-accent) 24%, transparent);\n  border-top-color: var(--ps-accent);\n  animation: ps-spin 0.7s linear infinite;\n}\n@media (prefers-reduced-motion: reduce) {\n  .ps-skel-spinner {\n    animation: ps-pulse 1.1s ease-in-out infinite;\n  }\n}\n.ps-skel-paper {\n  width: min(70%, 720px);\n  aspect-ratio: 8.5 / 11;\n  border-radius: 0;\n  background: linear-gradient(\n    100deg,\n    var(--ps-paper) 30%,\n    color-mix(in srgb, var(--ps-paper) 88%, var(--ps-hairline)) 50%,\n    var(--ps-paper) 70%\n  );\n  background-size: 220% 100%;\n  box-shadow: var(--ps-shadow), var(--ps-ring);\n  animation: ps-shimmer 1.4s ease-in-out infinite;\n}\n@keyframes ps-shimmer {\n  from {\n    background-position: 180% 0;\n  }\n  to {\n    background-position: -80% 0;\n  }\n}\n\n/* ── In-stage error state ────────────────────────────────────────────────── */\n/* Shown via .ps-stage[data-error=\"1\"] on loader:error; cleared on the next\n * load-started. Without it a corrupt file leaves a blank dark stage (the 11px\n * corner status token is invisible at dev:false). Non-modal: pointer-events\n * none, the chrome/explorer stay usable to pick another document. */\n.ps-error {\n  position: absolute;\n  inset: 0;\n  display: none;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: var(--ps-s2);\n  text-align: center;\n  padding: var(--ps-s5);\n  pointer-events: none;\n  z-index: 3;\n}\n.ps-stage[data-error=\"1\"] .ps-error {\n  display: flex;\n}\n/* The skeleton must never sit over the error (a slow failing load). */\n.ps-stage[data-error=\"1\"] .ps-skeleton {\n  opacity: 0;\n  visibility: hidden;\n}\n.ps-error-icon {\n  font-size: 26px;\n  line-height: 1;\n  color: var(--ps-err);\n  margin-bottom: var(--ps-s1);\n}\n.ps-error-title {\n  font-family: var(--ps-font-ui);\n  font-size: 14px;\n  font-weight: 600;\n  color: var(--ps-text);\n}\n.ps-error-msg {\n  font-family: var(--ps-font-mono);\n  font-size: 11px;\n  line-height: 1.5;\n  color: var(--ps-text-muted);\n  max-width: min(520px, 86%);\n  word-break: break-word;\n}\n\n/* ── One-click local fonts ───────────────────────────────────────────────── */\n/* A small floating pill over the stage, shown only when enabling installed\n * fonts would visibly help (permission prompt-able + a substituting family\n * whose local candidate is CSS-visible). Hidden via [hidden]. */\n.ps-localfonts-cta {\n  position: absolute;\n  top: var(--ps-s3);\n  right: var(--ps-s3);\n  z-index: 4;\n  font-family: var(--ps-font-ui);\n  font-size: 11.5px;\n  font-weight: 600;\n  color: var(--ps-text);\n  background: var(--ps-panel);\n  border: 1px solid var(--ps-hairline-strong);\n  border-radius: 0;\n  padding: 6px 12px;\n  cursor: pointer;\n  box-shadow: var(--ps-shadow);\n  transition: background 120ms ease, border-color 120ms ease;\n}\n.ps-localfonts-cta:hover {\n  background: var(--ps-accent-soft);\n  border-color: var(--ps-accent);\n}\n.ps-localfonts-cta[hidden] {\n  display: none;\n}\n\n/* ── Dev instrument ──────────────────────────────────────────────────────── */\n.ps-dev {\n  flex: 0 0 auto;\n  display: none;\n  flex-direction: column;\n  background: var(--ps-inset);\n  border-top: 1px solid var(--ps-hairline-strong);\n  font-family: var(--ps-font-mono);\n  z-index: 6;\n}\n.parasma-snippet[data-dev=\"1\"] .ps-dev {\n  display: flex;\n}\n.ps-dev-bar {\n  display: flex;\n  align-items: center;\n  gap: var(--ps-s2);\n  height: 32px;\n  padding: 0 var(--ps-s3);\n  border-bottom: 1px solid transparent;\n  font-size: 11px;\n  color: var(--ps-text-muted);\n  cursor: default;\n  /* Narrow hosts: the bar must clip, not shatter its tabs over the stage. */\n  overflow: hidden;\n}\n/* The tab strip (was missing a rule entirely — block-flow at ≤780px). It\n * scrolls (hidden scrollbar) so IMAGES/BUS stay reachable on narrow hosts. */\n.ps-dev-tabs {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  flex: 0 1 auto;\n  min-width: 0;\n  overflow-x: auto;\n  scrollbar-width: none;\n}\n.ps-dev-tabs::-webkit-scrollbar {\n  display: none;\n}\n.ps-dev-tab {\n  flex: 0 0 auto;\n}\n.ps-dev[data-open=\"1\"] .ps-dev-bar {\n  border-bottom-color: var(--ps-hairline);\n}\n.ps-dev-title {\n  font-weight: 700;\n  letter-spacing: 0.12em;\n  color: var(--ps-text);\n}\n.ps-dev-tab {\n  appearance: none;\n  background: transparent;\n  border: none;\n  color: var(--ps-text-muted);\n  font-family: var(--ps-font-mono);\n  font-size: 11px;\n  letter-spacing: 0.06em;\n  padding: 4px 7px;\n  border-radius: 0;\n  cursor: pointer;\n  transition: color 0.12s ease, background 0.12s ease;\n}\n.ps-dev-tab:hover {\n  color: var(--ps-text);\n}\n.ps-dev-tab[aria-selected=\"true\"] {\n  color: var(--ps-text);\n  background: var(--ps-accent-soft);\n}\n.ps-dev-build {\n  font-size: 10px;\n  color: var(--ps-text-faint);\n  /* The build id is long (parserInfo string) — ellipsize, never wrap/overflow. */\n  flex: 0 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.ps-dev-build b {\n  color: var(--ps-text-muted);\n  font-weight: 500;\n}\n.ps-dev-toggle {\n  margin-left: auto;\n  display: inline-flex;\n  align-items: center;\n  gap: var(--ps-s2);\n}\n.ps-dev-chord {\n  color: var(--ps-text-faint);\n  font-size: 10px;\n}\n.ps-dev-disc {\n  appearance: none;\n  background: transparent;\n  border: none;\n  color: var(--ps-text-muted);\n  cursor: pointer;\n  font-size: 12px;\n  padding: 2px 4px;\n}\n.ps-dev-disc:hover {\n  color: var(--ps-text);\n}\n.ps-dev-body {\n  display: none;\n  height: 220px;\n  overflow: auto;\n  padding: var(--ps-s2) 0;\n}\n.ps-dev[data-open=\"1\"] .ps-dev-body {\n  display: block;\n}\n.ps-dev-pane {\n  display: none;\n  padding: 0 var(--ps-s3);\n}\n.ps-dev-pane[data-active=\"1\"] {\n  display: block;\n}\n\n/* Structured log / bus rows. */\n.ps-row {\n  display: grid;\n  grid-template-columns: 64px 14px 64px 1fr;\n  align-items: baseline;\n  gap: var(--ps-s2);\n  padding: 2px 4px;\n  font-size: 11px;\n  line-height: 1.5;\n  border-radius: 0;\n}\n.ps-row:hover {\n  background: var(--ps-canvas);\n}\n.ps-row .ps-t {\n  text-align: right;\n  color: var(--ps-text-faint);\n  font-feature-settings: \"tnum\" 1, \"zero\" 1;\n}\n.ps-row .ps-lvl {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--ps-text-faint);\n  align-self: center;\n}\n.ps-row[data-lvl=\"ok\"] .ps-lvl {\n  background: var(--ps-ok);\n}\n.ps-row[data-lvl=\"err\"] .ps-lvl {\n  background: var(--ps-err);\n}\n.ps-row[data-lvl=\"info\"] .ps-lvl {\n  background: var(--ps-text-muted);\n}\n.ps-row .ps-chan {\n  color: var(--ps-text-muted);\n  font-size: 10px;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n}\n.ps-row .ps-msg {\n  color: var(--ps-text);\n  word-break: break-word;\n}\n.ps-row[data-lvl=\"err\"] .ps-msg {\n  color: var(--ps-err);\n}\n\n/* INFO + IMAGES table. */\n.ps-kv {\n  display: grid;\n  grid-template-columns: max-content 1fr;\n  gap: 2px var(--ps-s4);\n  font-size: 11px;\n}\n.ps-kv dt {\n  color: var(--ps-text-muted);\n}\n.ps-kv dd {\n  margin: 0;\n  color: var(--ps-text);\n  font-feature-settings: \"tnum\" 1, \"zero\" 1;\n}\n.ps-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 11px;\n}\n.ps-table th {\n  text-align: left;\n  color: var(--ps-text-muted);\n  font-weight: 500;\n  padding: 3px 8px;\n  border-bottom: 1px solid var(--ps-hairline);\n}\n.ps-table td {\n  padding: 3px 8px;\n  color: var(--ps-text);\n  border-bottom: 1px solid var(--ps-hairline);\n  font-feature-settings: \"tnum\" 1, \"zero\" 1;\n}\n.ps-table td .ps-yes {\n  color: var(--ps-ok);\n}\n.ps-table td .ps-no {\n  color: var(--ps-text-faint);\n}\n/* FONTS live pane: rows whose origin/resolves-now/variants changed since the\n   last render flash briefly so a toggle's live effect is visible at a glance. */\n.ps-table tr.ps-flash td {\n  animation: ps-flash-fade 1.4s ease-out;\n}\n@keyframes ps-flash-fade {\n  from {\n    background: color-mix(in srgb, var(--ps-ok) 28%, transparent);\n  }\n  to {\n    background: transparent;\n  }\n}\n\n/* TIMING phase bars. */\n.ps-phase {\n  display: grid;\n  grid-template-columns: 92px 1fr 56px;\n  align-items: center;\n  gap: var(--ps-s2);\n  font-size: 11px;\n  padding: 3px 4px;\n}\n.ps-phase .ps-pn {\n  color: var(--ps-text-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  font-size: 10px;\n}\n.ps-phase .ps-bar {\n  height: 6px;\n  border-radius: 0;\n  background: var(--ps-accent);\n  opacity: 0.85;\n  min-width: 2px;\n}\n.ps-phase .ps-ms {\n  text-align: right;\n  color: var(--ps-text);\n  font-feature-settings: \"tnum\" 1, \"zero\" 1;\n}\n\n.ps-dev-copy {\n  margin: var(--ps-s2) var(--ps-s3);\n  height: 26px;\n  padding: 0 var(--ps-s3);\n  font-family: var(--ps-font-mono);\n  font-size: 11px;\n}\n\n/* ── Load reveal (first mount only) ──────────────────────────────────────── */\n@keyframes ps-rise {\n  from {\n    opacity: 0;\n    transform: translateY(6px);\n  }\n  to {\n    opacity: 1;\n    transform: none;\n  }\n}\n@keyframes ps-page-in {\n  from {\n    opacity: 0;\n    transform: scale(0.985);\n  }\n  to {\n    opacity: 1;\n    transform: none;\n  }\n}\n.parasma-snippet.is-revealing .ps-toolbar > * {\n  animation: ps-rise 0.34s cubic-bezier(0.2, 0.7, 0.2, 1) both;\n  animation-delay: var(--ps-d, 0ms);\n}\n.parasma-snippet.is-revealing .ps-pages {\n  animation: ps-page-in 0.26s cubic-bezier(0.2, 0.7, 0.2, 1) both;\n}\n.parasma-snippet.is-revealing .ps-dev {\n  animation: ps-rise 0.34s cubic-bezier(0.2, 0.7, 0.2, 1) both;\n  animation-delay: 220ms;\n}\n\n/* ── Explorer panel (opt-in app-shell sidebar) ───────────────────────────── */\n.ps-explorer {\n  flex: 0 0 var(--ps-explorer-w);\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  background: var(--ps-panel);\n  border-right: 1px solid var(--ps-hairline);\n  overflow: hidden;\n  transition: flex-basis 0.22s cubic-bezier(0.2, 0.7, 0.2, 1),\n    border-color 0.22s ease;\n  z-index: 7;\n}\n.ps-explorer[data-collapsed] {\n  flex-basis: 0;\n  border-right-color: transparent;\n}\n/* Inner wrapper holds a fixed width so contents don't reflow during collapse. */\n.ps-explorer-inner {\n  width: var(--ps-explorer-w);\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n}\n\n.ps-explorer-head {\n  flex: 0 0 auto;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  height: var(--ps-toolbar-h);\n  padding: 0 var(--ps-s2) 0 var(--ps-s4);\n  border-bottom: 1px solid var(--ps-hairline);\n}\n.ps-explorer-title {\n  font-family: var(--ps-font-ui);\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: var(--ps-text-muted);\n}\n.ps-explorer-collapse {\n  font-size: 16px;\n}\n\n.ps-explorer-filter {\n  flex: 0 0 auto;\n  padding: var(--ps-s2) var(--ps-s3);\n  border-bottom: 1px solid var(--ps-hairline);\n}\n.ps-explorer-search {\n  width: 100%;\n  height: 28px;\n  padding: 0 var(--ps-s2);\n  font-family: var(--ps-font-ui);\n  font-size: 12px;\n  color: var(--ps-text);\n  background: var(--ps-inset);\n  border: 1px solid var(--ps-hairline);\n  border-radius: 0;\n  outline: none;\n  transition: border-color 0.12s ease, box-shadow 0.12s ease;\n}\n.ps-explorer-search::placeholder {\n  color: var(--ps-text-faint);\n}\n.ps-explorer-search:focus {\n  border-color: var(--ps-accent);\n  box-shadow: 0 0 0 2px var(--ps-accent-soft);\n}\n\n.ps-explorer-body {\n  flex: 1 1 auto;\n  min-height: 0;\n  position: relative;\n}\n.ps-explorer-tree {\n  height: 100%;\n  overflow-y: auto;\n  padding: var(--ps-s2) var(--ps-s1) var(--ps-s3);\n}\n.ps-explorer-empty {\n  display: none;\n  padding: var(--ps-s4) var(--ps-s4);\n  font-family: var(--ps-font-ui);\n  font-size: 12px;\n  line-height: 1.5;\n  color: var(--ps-text-faint);\n}\n\n/* Rows: disclosure / format / group headers. */\n.ps-tree-row {\n  display: flex;\n  align-items: center;\n  gap: var(--ps-s2);\n  height: 28px;\n  padding: 0 var(--ps-s2);\n  border-radius: 0;\n  cursor: pointer;\n  user-select: none;\n  transition: background 0.12s ease;\n}\n.ps-tree-row:hover {\n  background: var(--ps-inset);\n}\n.ps-disc {\n  flex: 0 0 12px;\n  width: 12px;\n  height: 12px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: var(--ps-text-faint);\n  transition: color 0.12s ease;\n}\n.ps-disc svg {\n  display: block;\n}\n.ps-tree-row:hover .ps-disc {\n  color: var(--ps-text-muted);\n}\n.ps-fmt-dot {\n  flex: 0 0 7px;\n  width: 7px;\n  height: 7px;\n  /* A circle, not a corner-radius — format/status indicators stay round while\n   * the rest of the (all-square) chrome has sharp 90° corners. */\n  border-radius: 50%;\n  background: var(--ps-text-faint);\n}\n.ps-fmt-dot[data-fmt=\"docx\"] { background: var(--ps-fmt-docx); }\n.ps-fmt-dot[data-fmt=\"xlsx\"] { background: var(--ps-fmt-xlsx); }\n.ps-fmt-dot[data-fmt=\"pptx\"] { background: var(--ps-fmt-pptx); }\n.ps-fmt-dot[data-fmt=\"csv\"]  { background: var(--ps-fmt-csv); }\n\n.ps-tree-label {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-family: var(--ps-font-ui);\n  font-size: 12px;\n  color: var(--ps-text);\n}\n.ps-tree-row.is-format .ps-tree-label {\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--ps-text-muted);\n}\n.ps-tree-row.is-group .ps-tree-label {\n  font-size: 11.5px;\n  color: var(--ps-text-muted);\n}\n.ps-tree-badge {\n  flex: 0 0 auto;\n  font-family: var(--ps-font-mono);\n  font-size: 10px;\n  color: var(--ps-text-faint);\n  font-feature-settings: \"tnum\" 1, \"zero\" 1;\n  padding-right: 2px;\n}\n\n/* Children box with a hairline guide-line. */\n.ps-tree-children {\n  margin-left: 12px;\n  padding-left: var(--ps-s2);\n  border-left: 1px solid var(--ps-hairline);\n}\n\n/* Leaves. */\n.ps-tree-leaf {\n  position: relative;\n  display: flex;\n  align-items: center;\n  height: 26px;\n  padding: 0 var(--ps-s2);\n  margin-left: 6px;\n  border-radius: 0;\n  cursor: pointer;\n  outline: none;\n  transition: background 0.12s ease, color 0.12s ease;\n}\n.ps-leaf-label {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-family: var(--ps-font-ui);\n  font-size: 12px;\n  color: var(--ps-text-muted);\n}\n.ps-tree-leaf:hover {\n  background: var(--ps-inset);\n}\n.ps-tree-leaf:hover .ps-leaf-label {\n  color: var(--ps-text);\n}\n.ps-tree-leaf:focus-visible {\n  /* A 1px solid accent ring + soft halo — the soft wash alone was near-invisible\n   * for keyboard navigation. */\n  box-shadow: inset 0 0 0 1px var(--ps-accent), 0 0 0 2px var(--ps-accent-soft);\n}\n/* Active leaf — the ONE amber accent moment: 2px left bar + soft wash + label. */\n.ps-tree-leaf.is-selected {\n  background: var(--ps-accent-soft);\n}\n.ps-tree-leaf.is-selected::before {\n  content: \"\";\n  position: absolute;\n  left: 0;\n  top: 4px;\n  bottom: 4px;\n  width: 2px;\n  border-radius: 0;\n  background: var(--ps-accent);\n}\n.ps-tree-leaf.is-selected .ps-leaf-label {\n  color: var(--ps-accent);\n  font-weight: 600;\n}\n\n/* Toolbar panel-toggle reflects collapsed state. */\n.ps-panel-toggle[aria-pressed=\"true\"] {\n  color: var(--ps-text);\n}\n\n/* ── Thin themed scrollbars on every scroll container ────────────────────── */\n/* The OS default chunky light scrollbar fights the dark chrome; theme it to\n * the hairline tokens (Firefox scrollbar-* + WebKit pseudo-elements). */\n.ps-viewer,\n.ps-gridview,\n.ps-tabs,\n.ps-comments-list,\n.ps-explorer-tree,\n.ps-dev-body {\n  scrollbar-width: thin;\n  scrollbar-color: var(--ps-hairline-strong) transparent;\n}\n.ps-viewer::-webkit-scrollbar,\n.ps-gridview::-webkit-scrollbar,\n.ps-tabs::-webkit-scrollbar,\n.ps-comments-list::-webkit-scrollbar,\n.ps-explorer-tree::-webkit-scrollbar,\n.ps-dev-body::-webkit-scrollbar {\n  width: 8px;\n  height: 8px;\n}\n.ps-viewer::-webkit-scrollbar-thumb,\n.ps-gridview::-webkit-scrollbar-thumb,\n.ps-tabs::-webkit-scrollbar-thumb,\n.ps-comments-list::-webkit-scrollbar-thumb,\n.ps-explorer-tree::-webkit-scrollbar-thumb,\n.ps-dev-body::-webkit-scrollbar-thumb {\n  background: var(--ps-hairline-strong);\n  border-radius: 0;\n}\n.ps-viewer::-webkit-scrollbar-track,\n.ps-gridview::-webkit-scrollbar-track,\n.ps-tabs::-webkit-scrollbar-track,\n.ps-comments-list::-webkit-scrollbar-track,\n.ps-explorer-tree::-webkit-scrollbar-track,\n.ps-dev-body::-webkit-scrollbar-track {\n  background: transparent;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .parasma-snippet *,\n  .parasma-snippet *::before,\n  .parasma-snippet *::after {\n    animation-duration: 0ms !important;\n    animation-delay: 0ms !important;\n    transition-duration: 0ms !important;\n  }\n}\n";
